--
-- exercises_min.sql - corpus minimo para los tests de integracion.
--
-- Mismo DDL que infra/vector-db/ddl/001_*_part-01.sql, con 10 filas en vez de
-- las ~1300 del volcado real (283 MB, varios minutos de arranque). Los vectores
-- son deterministas para que la recuperacion sea reproducible en CI.
--

CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE public.exercises (
    id bigint NOT NULL PRIMARY KEY,
    name text NOT NULL,
    category text,
    body_part text,
    equipment text,
    muscle_group text,
    target text,
    secondary_muscles text[],
    instructions_en text,
    instructions_tr text,
    created_at timestamp with time zone,
    metadata_vector public.vector(384)
);

CREATE TABLE public.exercise_media (
    id serial PRIMARY KEY,
    exercise_id bigint NOT NULL,
    image_path text,
    gif_path text,
    image_data bytea,
    gif_data bytea
);

